Here are three independent implementations — **TypeScript (Node.js)**, **Python**, and **Go** — that stream a large JSON array from a file without loading it entirely into memory.

---

## 1. TypeScript / Node.js

```typescript
import { createReadStream } from 'fs';
import { pipeline } from 'stream/promises';

interface Item {
  id: number;
  name: string;
}

/**
 * Generator that yields items from a large JSON array stored in a file.
 *
 * The input file is expected to contain one JSON object per line (NDJSON — Newline Delimited
 * JSON). This avoids loading the whole file into memory and lets you process each record as it
 * arrives. Each yielded value matches the shape of `Item`.
 *
 * @param filePath Path to a .jsonl / NDJSON file containing one JSON object per line.
 */
export function* streamJsonArrayFile(filePath: string): AsyncGenerator<Item, undefined> {
  const readStream = createReadStream(filePath);

  for await (const chunk of readStream) {
    // `chunk` is a Buffer; convert to string and trim whitespace
    const rawLine = chunk.toString().trim();
    if (!rawLine) continue;

    try {
      const parsed: Item = JSON.parse(rawLine);
      yield parsed;
    } catch (e) {
      console.error(`Failed to parse line "${chunk.toString()}":`, e);
    }
  }
}
```

**Usage:**

```typescript
import { streamJsonArrayFile } from './stream-json-array.ts';

async function main() {
  const generator = streamJsonArrayFile('./data/records.jsonl');
  for await (const item of generator) {
    console.log(item);   // e.g. { id: 1, name: 'Alice' }
  }
}
```

---

## 2. Python

