import json


def stream_json_array(filepath: str):
    """
    Generator that yields parsed JSON objects from a large file containing one object per line (NDJSON).

    Yields each item as a dict without loading the entire file into memory.
    Skips blank lines and prints an error for malformed lines.
    """
    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:          # iterates lazily over the file
            line = line.strip()
            if not line:
                continue
            try:
                item = json.loads(line)
                yield item
            except json.JSONDecodeError as e:
                print(f"Skipping invalid JSON on line {line!r}: {e}")
