## 3. Go

```go
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
)

// Item represents a single element of the array.
type Item struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

// StreamJSONArray reads a file line-by-line and yields each parsed item without loading
// the entire file into memory. The input is expected to be NDJSON (one JSON object per line).
func StreamJSONArray(filePath string) <-chan Item {
	file, err := os.Open(filePath)
	if err != nil {
		return nil // caller handles error
	}
	defer file.Close()

	ch := make(chan Item, 1024)

	go func() {
		defer close(ch) // signal when done (or you can keep draining)
		scanner := bufio.NewScanner(file)
		for scanner.Scan() {
			line := scanner.Text()
			if line == "" {
				continue
		 }
			var item Item
			if err := json.Unmarshal([]byte(line), &item); err != nil {
				fmt.Fprintf(os.Stderr, "Skipping invalid JSON on line: %s — %v\n", line, err)
				// skip this line; continue scanning
				continue
		 }
			ch <- item
		}
	}()

	return ch
}

func main() {
	go func() { _ = StreamJSONArray("./data/records.jsonl") }()
	for item := range StreamJSONArray("./data/records.jsonl") {
		fmt.Println(item)
	}
}
```

**Note:** Go's `bufio.Scanner` reads line-by-line, so this works for NDJSON. For a single giant JSON array on one line (not newline-delimited), you would need an external streaming parser — but the pattern above is the standard approach.

