export interface MemoizeOptions {
  /** Time-to-live in ms. Entries older than this are treated as misses. Default 60_000. */
  ttlMs?: number;
  /** Maximum number of cached entries. Least-recently-used entries are evicted. Default 1000. */
  maxEntries?: number;
  /** Clock for testing. Default Date.now. */
  now?: () => number;
  /** Key builder. Default: JSON.stringify of the argument list. */
  keyFn?: (...args: unknown[]) => string;
}

export interface Memoized<A extends unknown[], R> {
  (...args: A): R;
  /** Drop every cached entry. */
  clear(): void;
  /** Drop one entry by its computed key. */
  delete(...args: A): boolean;
  /** Number of live (non-expired) entries. */
  size(): number;
  /** Cache statistics — useful for tuning ttlMs/maxEntries. */
  stats(): { hits: number; misses: number; evictions: number; expirations: number };
}

interface Entry<R> {
  value: R;
  expiresAt: number;
}

/**
 * Memoize a synchronous function with a TTL + LRU-bounded cache.
 *
 * Invalidation story:
 * - TTL: an entry is stale once `now() >= expiresAt`; it is dropped on the next read.
 * - LRU: when `maxEntries` is exceeded the least-recently-used entry is evicted.
 * - Manual: `clear()` and `delete(...args)`.
 *
 * Complexity: O(1) average per call (Map preserves insertion order, so LRU touch is
 * delete+set). Space: O(maxEntries).
 *
 * Only successful calls are cached — a throw propagates and caches nothing.
 */
export function memoize<A extends unknown[], R>(
  fn: (...args: A) => R,
  opts: MemoizeOptions = {},
): Memoized<A, R> {
  const ttlMs = opts.ttlMs ?? 60_000;
  const maxEntries = opts.maxEntries ?? 1000;
  const now = opts.now ?? Date.now;
  const keyFn = opts.keyFn ?? ((...args: unknown[]) => JSON.stringify(args));

  const cache = new Map<string, Entry<R>>();
  const counters = { hits: 0, misses: 0, evictions: 0, expirations: 0 };

  const memoized = ((...args: A): R => {
    const key = keyFn(...args);
    const hit = cache.get(key);
    if (hit !== undefined) {
      if (now() < hit.expiresAt) {
        counters.hits++;
        // Refresh LRU position: re-insert at the tail.
        cache.delete(key);
        cache.set(key, hit);
        return hit.value;
      }
      cache.delete(key);
      counters.expirations++;
    }

    counters.misses++;
    const value = fn(...args);
    cache.set(key, { value, expiresAt: now() + ttlMs });
    if (cache.size > maxEntries) {
      const oldest = cache.keys().next();
      if (!oldest.done) {
        cache.delete(oldest.value);
        counters.evictions++;
      }
    }
    return value;
  }) as Memoized<A, R>;

  memoized.clear = () => { cache.clear(); };
  memoized.delete = (...args: A) => cache.delete(keyFn(...args));
  memoized.size = () => {
    const t = now();
    let live = 0;
    for (const e of cache.values()) if (t < e.expiresAt) live++;
    return live;
  };
  memoized.stats = () => ({ ...counters });
  return memoized;
}

/**
 * Async variant. Concurrent calls with the same key share one in-flight promise,
 * so a slow function is not invoked N times for N simultaneous callers.
 * Rejected promises are not cached.
 */
export function memoizeAsync<A extends unknown[], R>(
  fn: (...args: A) => Promise<R>,
  opts: MemoizeOptions = {},
): Memoized<A, Promise<R>> {
  const ttlMs = opts.ttlMs ?? 60_000;
  const maxEntries = opts.maxEntries ?? 1000;
  const now = opts.now ?? Date.now;
  const keyFn = opts.keyFn ?? ((...args: unknown[]) => JSON.stringify(args));

  const cache = new Map<string, Entry<Promise<R>>>();
  const counters = { hits: 0, misses: 0, evictions: 0, expirations: 0 };

  const memoized = ((...args: A): Promise<R> => {
    const key = keyFn(...args);
    const hit = cache.get(key);
    if (hit !== undefined) {
      if (now() < hit.expiresAt) {
        counters.hits++;
        cache.delete(key);
        cache.set(key, hit);
        return hit.value;
      }
      cache.delete(key);
      counters.expirations++;
    }

    counters.misses++;
    const promise = fn(...args).catch((err: unknown) => {
      // Do not cache failures — the next caller retries.
      cache.delete(key);
      throw err;
    });
    cache.set(key, { value: promise, expiresAt: now() + ttlMs });
    if (cache.size > maxEntries) {
      const oldest = cache.keys().next();
      if (!oldest.done) {
        cache.delete(oldest.value);
        counters.evictions++;
      }
    }
    return promise;
  }) as Memoized<A, Promise<R>>;

  memoized.clear = () => { cache.clear(); };
  memoized.delete = (...args: A) => cache.delete(keyFn(...args));
  memoized.size = () => {
    const t = now();
    let live = 0;
    for (const e of cache.values()) if (t < e.expiresAt) live++;
    return live;
  };
  memoized.stats = () => ({ ...counters });
  return memoized;
}
