"""TTL + LRU memoization for sync and async callables.

Invalidation story:
  * TTL      - an entry is stale once ``now() >= expires_at``; dropped on next read.
  * LRU      - when ``max_entries`` is exceeded the least-recently-used entry is evicted.
  * Manual   - ``clear()`` and ``delete(*args)``.

Complexity: O(1) average per call (dict preserves insertion order, so an LRU touch is
``del`` + re-insert). Space: O(max_entries).

Only successful calls are cached - an exception propagates and caches nothing.
"""

from __future__ import annotations

import asyncio
import functools
import json
import time
from dataclasses import dataclass, field
from typing import Any, Awaitable, Callable, Generic, TypeVar

R = TypeVar("R")

DEFAULT_TTL_S = 60.0
DEFAULT_MAX_ENTRIES = 1000


def _default_key(args: tuple[Any, ...], kwargs: dict[str, Any]) -> str:
    # sort_keys keeps {"a":1,"b":2} and {"b":2,"a":1} on the same cache line.
    return json.dumps([args, kwargs], sort_keys=True, default=repr)


@dataclass
class _Entry(Generic[R]):
    value: R
    expires_at: float


@dataclass
class _Counters:
    hits: int = 0
    misses: int = 0
    evictions: int = 0
    expirations: int = 0

    def as_dict(self) -> dict[str, int]:
        return {
            "hits": self.hits,
            "misses": self.misses,
            "evictions": self.evictions,
            "expirations": self.expirations,
        }


class _Cache(Generic[R]):
    """Shared TTL+LRU store. Not thread-safe by itself; see ``memoize`` for the lock."""

    def __init__(
        self,
        ttl_s: float,
        max_entries: int,
        now: Callable[[], float],
    ) -> None:
        self._ttl_s = ttl_s
        self._max_entries = max_entries
        self._now = now
        self._data: dict[str, _Entry[R]] = {}
        self.counters = _Counters()

    def get(self, key: str) -> tuple[bool, R | None]:
        entry = self._data.get(key)
        if entry is None:
            return False, None
        if self._now() < entry.expires_at:
            self.counters.hits += 1
            # Refresh LRU position: re-insert at the tail.
            del self._data[key]
            self._data[key] = entry
            return True, entry.value
        del self._data[key]
        self.counters.expirations += 1
        return False, None

    def put(self, key: str, value: R) -> None:
