        build_key = key_fn or (lambda *a, **kw: _default_key(a, kw))

        @functools.wraps(target)
        def wrapper(*args: Any, **kwargs: Any) -> R:
            key = build_key(*args, **kwargs)
            found, value = cache.get(key)
            if found:
