        wrapper.cache_delete = lambda *a, **kw: cache.drop(build_key(*a, **kw))  # type: ignore[attr-defined]
        wrapper.cache_size = cache.size  # type: ignore[attr-defined]
        wrapper.cache_stats = cache.counters.as_dict  # type: ignore[attr-defined]
        return wrapper

    return decorate(fn) if fn is not None else decorate


def memoize_async(
    fn: Callable[..., Awaitable[R]] | None = None,
    *,
    ttl_s: float = DEFAULT_TTL_S,
    max_entries: int = DEFAULT_MAX_ENTRIES,
    now: Callable[[], float] = time.monotonic,
    key_fn: Callable[..., str] | None = None,
) -> Callable[..., Awaitable[R]]:
