    """

    def decorate(target: Callable[..., Awaitable[R]]) -> Callable[..., Awaitable[R]]:
        cache: _Cache[asyncio.Task[R]] = _Cache(ttl_s, max_entries, now)
        build_key = key_fn or (lambda *a, **kw: _default_key(a, kw))

        @functools.wraps(target)
