/**
 * Returns the maximum sum of any K consecutive elements in arr.
 * If no valid window exists (e.g., k <= 0 or k > arr.length) returns 0.
 */
function maxSumOfKConsecutive(arr: number[], k: number): number {
  if (!arr || k <= 0 || k > arr.length) return 0;

  // initialise the first window
  let windowSum = 0;
  for (let i = 0; i < k; i++) windowSum += arr[i];
  let maxSum = windowSum;

  // slide the window forward
  for (let i = k; i < arr.length; i++) {
    windowSum += arr[i];          // add new element
    windowSum -= arr[i - k];      // remove leftmost element of previous window
    if (windowSum > maxSum) maxSum = windowSum;
  }

  return maxSum;
}

