        return vec![];
    }
    let mut res = Vec::with_capacity(n - k + 1);
    let mut window_sum: f64 = 0.0;
    for &val in &arr[..k] {
        window_sum += val;
    }
    res.push(window_sum);

    for i in k..n {
        window_sum += arr[i] - arr[i - k];
        res.push(window_sum);
    }
    res
