# bfs.py
from collections import deque
from typing import Dict, List, Set

def bfs(graph: Dict[str, List[str]], start: str, target: str) -> List[str]:
    """
    Return one shortest path from `start` to `target` in an undirected graph.

    Parameters:
        graph: dict mapping each node to a list of its neighbours.
        start: starting vertex (must exist).
        target: destination vertex (must exist).

    Returns:
        A list of nodes forming the shortest path, e.g. [start, ..., target].
    """
    if start not in graph or target not in graph:
        raise KeyError("Start or target node not found in the graph")

    # distance map and parent map
    dist: Dict[str, int] = {start: 0}
    parents: Dict[str, str] = {start: None}
    q = deque([start])

    while q:
        node = q.popleft()
        if node == target:
            break
        for neighbour in graph.get(node, []):
            if neighbour not in dist:
                dist[neighbour] = dist[node] + 1
                parents[neighbour] = node
                q.append(neighbour)

    # Reconstruct path by walking backwards from `target` to `start`
    path: List[str] = []
    current: str | None = target
    while current is not None:
        path.append(current)
        current = parents.get(current)  # type: ignore[arg-type]
    path.reverse()
    return path


# Example usage:
if __name__ == "__main__":
    graph = {
        "A": ["B", "C"],
        "B": ["A", "D"],
        "C": ["A", "E"],
        "D": ["B"],
        "E": ["C"]
    }
    print(bfs(graph, "A", "E"))  # → ['A', 'C', 'E']
```

**Key points**

* `deque` guarantees O(1) pop from the left.  
* The first time we discover a node we record its distance and parent — this yields the shortest path in an unweighted graph.

