package main

import (
	"container/list"
	"fmt"
	"strings"
)

// Graph is represented as a map where each key is a node and its value is the list of neighbours.
type Graph map[string][]string

func BFS(graph Graph, start string, target string) []string {
	if graph == nil || !graph[start] != nil || !graph[target] != nil {
		return nil // or panic; here we return an empty slice to indicate failure
	}

	// queue holds nodes to explore (FIFO)
	q := list.New()
	q.PushBack(start)

	// visited set and parent map
	visited := make(map[string]bool)
	parent := make(map[string]string) // child -> parent

	for q.Len() > 0 {
		currentNode := q.Front().Value().(string)
		q.Remove(qFront())

		if currentNode == target {
			break
		}

		for _, neighbour := range graph[currentNode] {
			if !visited[neighbour] {
				visited[neighbour] = true
				parent[neighbour] = currentNode
				q.PushBack(neighbour)
			}
		}
	}

	// Reconstruct path from target back to start using parent map
	var path []string
	for node := target; node != ""; {
		if parent[node] == "" { // reached the root (start) without a recorded parent → stop
			break
		}
		path = append([]string{node}, path...)
		node = parent[node]
	}

	return path
}

func main() {
	g := Graph{
		"A": {"B", "C"},
		"B": {"A", "D"},
		"C": {"A", "E"},
		"D": {"B"},
		"E": {"C"},
	}
	fmt.Println(BFS(g, "A", "E")) // → [A C E] (order may vary)
}
```

