from collections import defaultdict, deque
from typing import List, Tuple

def topological_sort(vertices: List[int], edges: List[Tuple[int, int]]) -> List[int]:
    """
    vertices : list of all node ids (integers)
    edges    : list of directed edges as tuples (source, destination)

    Returns a list containing one ordering of the nodes such that
    for every edge u → v, u appears before v in the returned list.
    Assumes the input graph is a DAG; otherwise some vertices may be missing.
    """
    # ---- adjacency list -------------------------------------------------
    adj = defaultdict(list)
    indegree = {v: 0 for v in vertices}

    for src, dst in edges:
        adj[src].append(dst)          # build outgoing neighbours
        indegree[dst] += 1             # count incoming edges

    # ---- initialise queue with zero‑indegree nodes -----------------------
    queue = deque([v for v in vertices if indegree[v] == 0])

    order: List[int] = []

    while queue:
        node = queue.popleft()
        order.append(node)

        for nb in adj.get(node, []):
            indegree[nb] -= 1
            if indegree[nb] == 0:
                queue.append(nb)

    return order


# ------------------- Example usage -------------------
if __name__ == "__main__":
    verts = [5, 2, 4]
    edges = [(5, 2), (5, 4), (2, 1), (4, 3)]
    print(topological_sort(verts, edges))   # e.g. [5, 2, 4] or similar
```

**Key points**

* `defaultdict(list)` creates adjacency entries automatically.
* The algorithm runs in **O(V + E)** time and uses **O(V + E)** auxiliary structures.

