// Graph holds the vertex list and adjacency map.
type Graph struct {
	vertices []int // all vertices, indexed by their integer id
	adj      map[int][]int // adjacency list: source → target neighbours
}

// NewGraph builds a graph from an explicit vertex slice and edge pairs.
func NewGraph(vertices []int, edges [][]int) *Graph {
	g := &Graph{
		vertices: vertices,
		adj:      make(map[int][]int),
	}
	for _, e := range edges {
		if len(e) >= 2 {
			src, dst := e[0], e[1]
			g.adj[src] = append(g.adj[src], dst)
		}
	}
	return g
}

// TopologicalSort returns one possible topological ordering.
func (g *Graph) TopologicalSort() []int {
	// 1️⃣ compute indegree for every vertex
	indeg := make(map[int]int, len(g.vertices))
	for _, v := range g.vertices {
		indeg[v] = 0
	}
	for src, targets := range g.adj {
		for _, tgt := range targets {
			indeg[tgt]++
