/**
 * Returns an array containing every permutation of the input string.
 */
function permutations(str: string): string[] {
  const result: string[] = [];

  function helper(chars: string[], index: number) {
    if (index === chars.length) {
      result.push(chars.join(''));
      return;
    }
    for (let i = 0; i < chars.length; i++) {
      // swap
      const temp = chars[index];
      chars[index] = chars[i];
      chars[i] = temp;

      helper(chars, index + 1);

      // backtrack
      chars[index] = temp;
    }
  }

  const arr: string[] = str.split('');
  helper(arr, 0);
  return result;
}

// Example:
console.log(permutations("abc"));
