package main

import "fmt"

// Permutations returns all unique permutations of the input string.
func Permutations(str string) []string {
	// Work with runes to correctly handle Unicode characters.
	var chars []rune
	for _, r := range str {
		chars = append(chars, r)
	}
	var result []string

	fn helper(idx int, current string) {
		if idx == len(chars) {
			result = append(result, current)
			return
		}
		for i := idx; i < len(chars); i++ {
			// swap
			chars[idx], chars[i] = chars[i], chars[idx]
			fn helper(idx+1, string(current))
			// backtrack
			chars[idx], chars[i] = chars[i], chars[idx]
		}
	}
	fn helper(0, "")
	return result
}

func main() {
	fmt.Println(Permutations("abc"))
}
