fn permutations(s: &str) -> Vec<String> {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut result = vec![];

    fn dfs(idx: usize, path: String) {
        if idx == n {
            result.push(path);
            return;
        }
        for i in idx..n {
            // build next path by appending the character at position i
            let next_path = path.clone();
            next_path.push(chars[i]);
            dfs(idx + 1, next_path);
        }
    }

    dfs(0, String::new());
    result
}

