"""Permutations of a string."""

from typing import List


def permutations(s: str) -> List[str]:
    """Return every permutation of the characters in `s`.

    Duplicate characters produce duplicate permutations; use
    `unique_permutations` for distinct results only.
    """
    chars = list(s)
    result: List[str] = []
    used = [False] * len(chars)
    path: List[str] = []

    def walk() -> None:
        if len(path) == len(chars):
            result.append("".join(path))
            return
        for i, ch in enumerate(chars):
            if used[i]:
                continue
            used[i] = True
            path.append(ch)
            walk()
