/// Returns every permutation of the characters in `s`.
///
/// Duplicate characters produce duplicate permutations; use
/// `unique_permutations` for distinct results only.
pub fn permutations(s: &str) -> Vec<String> {
    let chars: Vec<char> = s.chars().collect();
    let mut result = Vec::new();
    let mut used = vec![false; chars.len()];
    let mut path = String::with_capacity(s.len());

    fn walk(chars: &[char], used: &mut [bool], path: &mut String, result: &mut Vec<String>) {
        if path.chars().count() == chars.len() {
            result.push(path.clone());
            return;
        }
        for i in 0..chars.len() {
            if used[i] {
                continue;
            }
            used[i] = true;
            path.push(chars[i]);
            walk(chars, used, path, result);
            path.pop();
            used[i] = false;
        }
    }

    walk(&chars, &mut used, &mut path, &mut result);
    result
}

/// Returns only distinct permutations of `s`.
pub fn unique_permutations(s: &str) -> Vec<String> {
    let mut chars: Vec<char> = s.chars().collect();
    chars.sort_unstable();
    let mut result = Vec::new();
    let mut used = vec![false; chars.len()];
    let mut path = String::with_capacity(s.len());

    fn walk(chars: &[char], used: &mut [bool], path: &mut String, result: &mut Vec<String>) {
        if path.chars().count() == chars.len() {
            result.push(path.clone());
            return;
        }
        for i in 0..chars.len() {
            if used[i] {
                continue;
            }
            // skip a duplicate that is not the first unused copy of its value
            if i > 0 && chars[i] == chars[i - 1] && !used[i - 1] {
                continue;
            }
            used[i] = true;
            path.push(chars[i]);
            walk(chars, used, path, result);
            path.pop();
            used[i] = false;
        }
    }

    walk(&chars, &mut used, &mut path, &mut result);
    result
}

fn main() {
    println!("{:?}", permutations("abc"));
    println!("{:?}", unique_permutations("aab"));
    println!("{} {:?}", permutations("").len(), permutations("a"));
}
